def _header(kicker: str, title: str, description: str = "") -> str:
    sub = f'<p class="sub">{escape(description)}</p>' if description else ""
    return (f'<div class="section-head"><div><p class="eyebrow">{escape(kicker)}</p>'
            f'<h2>{escape(title)}</h2></div>{sub}</div>')


def _card(title: str, body: str, link: str = "", href: str = "") -> str:
    anchor = f'<a href="{href}">{escape(link)} →</a>' if href else ""
    return f'<article class="card"><h3>{escape(title)}</h3><p>{escape(body)}</p>{anchor}</article>'


LOCKED_LABELS = {
    "tr": "Fonlar kilitli kalır",
    "es": "Fondos bloqueados",
    "pt-br": "Fundos bloqueados",
    "ru": "Средства заблокированы",
    "zh-cn": "资金继续锁定",
}


def localized_main(locale: str, data: dict, steps: str) -> str:
    """Render the same nine section types as the English landing page."""
    c = COPY[locale]
    english_note = {"tr": "İngilizce", "es": "inglés", "pt-br": "inglês", "ru": "английский", "zh-cn": "英语"}[locale]
    v, e, d, r, f, u, demo, guides, audience = (
        c[key] for key in ("video", "example", "dispute", "roles", "fees", "usdc", "demo", "guides", "audience")
    )
    links = c["links"]
    chapter_buttons = "".join(
        f'<button type="button" data-video-chapter="{i:02}" data-title="{escape(title, quote=True)}" '
        f'data-description="{escape(description, quote=True)}" aria-pressed="{"true" if i == 1 else "false"}">'
        f'<span>{i:02}</span>{escape(title)}</button>'
        for i, (title, description) in enumerate(c["chapters"], 1)
    )
    tracks = "".join(
        f'<track kind="subtitles" srclang="{language}" label="{label}" src="/assets/videos/01.{file_slug}.vtt">'
        for language, label, file_slug in (
            ("en", "English", "en"), ("tr", "Türkçe", "tr"), ("es", "Español", "es"),
            ("pt-BR", "Português (Brasil)", "pt-br"), ("ru", "Русский", "ru"), ("zh-CN", "简体中文", "zh-cn")
        )
    )
    example_cells = "".join(
        f'<div><small>{i} · {escape(label)}</small><strong>{amount}</strong><span>{escape(body)}</span></div>'
        for i, label, amount, body in (
            (1, e[5], "105.00 USDC", e[6]), (2, e[7], "5.00 USDC", e[8]),
            (3, e[9], "98.50 USDC", e[10]), (4, e[11], escape(LOCKED_LABELS[locale]), e[12])
        )
    )
    dispute_cells = "".join(
        f'<div><strong>{escape(d[i])}</strong><span>{escape(d[i + 1])}</span></div>'
        for i in (1, 3, 5)
    )
    role_cards = "".join(
        f'<article class="card role-card"><div class="role-symbol" aria-hidden="true">{symbol}</div>'
        f'<h3>{escape(r[i])}</h3><p>{escape(r[i + 1])}</p>'
        f'<a href="/mainnet?lang={locale}&amp;role={role}#start">{escape(r[i + 2])} →</a></article>'
        for i, symbol, role in ((3, "B", "buyer"), (6, "S", "seller"))
    )
    fee_cards = "".join(_card(f[i], f[i + 1]) for i in (3, 5, 7, 9))
    usdc_cards = (_card(u[3], u[4]) + _card(u[5], u[6]) + _card(u[7], u[8], links[1], f"/mainnet?lang={locale}#guide"))
    guide_cards = (_card(guides[3], guides[4], f"{guides[5]} ({english_note})", "/x402-vs-agent-escrow")
                   + _card(guides[6], guides[7], f"{guides[8]} ({english_note})", "/ai-agent-job-evidence"))
    audience_cards = "".join(_card(audience[i], audience[i + 1]) for i in (3, 5, 7, 9))
    first_title, first_desc = c["chapters"][0]
    return f'''<main>
<section class="section" id="how">{_header("AgentSolis", data["steps_title"])}<div class="flow flow-rail">{steps}</div></section>
<section class="section video-guide" id="videos">
{_header(v[0], v[1], v[2])}
<div class="video-guide-layout"><div class="video-guide-player">
<video id="explainerVideo" controls preload="none" playsinline width="1280" height="720" poster="/assets/videos/01-poster.png" src="/assets/videos/01-overview.mp4?v=20261028c" aria-label="{escape(first_title, quote=True)}" aria-describedby="videoGuideNotice">{tracks}</video>
<p id="videoGuideNotice" class="video-guide-notice">{escape(v[3])}</p></div>
<div class="video-guide-chapters" aria-label="{escape(v[1], quote=True)}">{chapter_buttons}
<div class="video-guide-copy" aria-live="polite"><h3 id="videoChapterTitle">{escape(first_title)}</h3><p id="videoChapterDescription">{escape(first_desc)}</p></div></div></div>
<p class="video-guide-links"><a href="/play" data-event="demo_click">{escape(links[0])} ({escape(english_note)}) →</a><a href="/mainnet?lang={locale}#guide" data-event="guide_click">{escape(links[1])} →</a></p></section>
<section class="section example-section">{_header(e[0], e[1], e[2])}
<div class="example-deal"><div class="example-title"><strong>{escape(e[3])}</strong><span>{escape(e[4])}</span></div>
<div class="example-grid">{example_cells}</div><p class="example-total"><strong>{escape(e[13])}:</strong> {escape(e[14])}</p></div>
<div class="dispute-explainer"><h3>{escape(d[0])}</h3><div class="dispute-grid">{dispute_cells}</div></div></section>
<section class="section">{_header(r[0], r[1], r[2])}<div class="cards roles">{role_cards}</div></section>
<section class="section trust-band">{_header(f[0], f[1], f[2])}<div class="cards facts">{fee_cards}</div>
<div class="translation-note">{escape(data["notice"])}</div></section>
<section class="section">{_header(u[0], u[1], u[2])}<div class="cards roles">{usdc_cards}</div></section>
<section class="section">{_header(demo[0], demo[1], demo[2])}<div class="notice"><strong>{escape(demo[3])}</strong> {escape(demo[4])}</div>
<a class="button" href="/play" data-event="demo_click">{escape(demo[5])} ({escape(english_note)}) →</a></section>
<section class="section">{_header(guides[0], guides[1], guides[2])}<div class="cards roles">{guide_cards}</div></section>
<section class="section" id="who-can-use">{_header(audience[0], audience[1], audience[2])}<div class="cards roles">{audience_cards}</div></section>
</main>'''
